<?php
require_once __DIR__ . '/lib/auth.php';
require_once __DIR__ . '/lib/high_value.php';
require_permission('view_procurement_intelligence');
require_once __DIR__ . '/config/db.php';

$supplierRows = supplier_performance_rows($pdo);
$overdueRows = purchase_order_overdue_rows($pdo);
$varianceRows = partial_delivery_variance_rows($pdo);
$workloadRows = procurement_workload_rows($pdo);
$quoteRows = quotation_comparison_rows($pdo);
$trendRows = project_consumption_rows($pdo);
$budgetRows = project_budget_rows($pdo);
$requestBoardRows = $pdo->query(
    "SELECT status, COUNT(*) AS total
     FROM material_requests
     GROUP BY status
     ORDER BY FIELD(status, 'submitted','under_review','approved','partially_reserved','reserved','ready_for_release','partially_released','released','received','completed','for_procurement','on_hold','cancelled','rejected')"
)->fetchAll();
$lowStockDrafts = $pdo->query(
    "SELECT m.material_code, m.material_name, u.name AS unit_name, l.name AS location_name,
            ROUND(GREATEST(b.quantity_on_hand - b.reserved_quantity - b.damaged_quantity, 0), 2) AS available_qty,
            m.reorder_point, GREATEST(m.reorder_point - GREATEST(b.quantity_on_hand - b.reserved_quantity - b.damaged_quantity, 0), 0) AS draft_qty
     FROM inventory_balances b
     JOIN materials m ON m.id = b.material_id
     JOIN units u ON u.id = m.unit_id
     JOIN locations l ON l.id = b.location_id
     WHERE m.is_active = 1 AND m.approval_status = 'approved' AND GREATEST(b.quantity_on_hand - b.reserved_quantity - b.damaged_quantity, 0) <= m.reorder_point
     ORDER BY draft_qty DESC
     LIMIT 30"
)->fetchAll();

$activePage = 'procurement_intelligence';
$title = 'Procurement Intelligence';
$eyebrow = 'SUPPLIER CONTROL';
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?= e($title) ?></title><?php require __DIR__ . '/partials/assets.php'; ?></head><body><div class="app-layout"><?php require __DIR__ . '/partials/sidebar.php'; ?><main class="app-main"><?php require __DIR__ . '/partials/header.php'; ?><div class="page-content">
<section class="monitoring-top-card ai-gradient-card"><div><span class="eyebrow light">PROCUREMENT INTELLIGENCE</span><h2>Procurement Intelligence</h2><p>Supplier lead-time performance, Supplier Reliability, overdue purchase orders, partial delivery variance, quotation comparison, project cost, and low-stock purchase request drafts.</p></div><div class="status-chip"><?= number_format(count($overdueRows)) ?> overdue PO(s)</div></section>
<section class="live-dashboard"><article class="live-card diagram-card wide"><div class="live-card-head"><div><span class="eyebrow">SUPPLIERS</span><h2>Supplier Delivery Reliability Score</h2></div></div><canvas class="chart-canvas" width="720" height="220" data-chart="supplier-bars" data-chart-data="<?= e(json_encode(array_map(static fn(array $row): array => ['label' => $row['company'], 'value' => (float) $row['reliability_score']], array_slice($supplierRows, 0, 8)), JSON_UNESCAPED_SLASHES)) ?>"></canvas></article><article class="live-card diagram-card"><div class="live-card-head"><div><span class="eyebrow">WORKLOAD</span><h2>Procurement Workload Board</h2></div></div><canvas class="chart-canvas" width="360" height="220" data-chart="workload-bars" data-chart-data="<?= e(json_encode(array_map(static fn(array $row): array => ['label' => $row['lane'] . ' ' . $row['status'], 'value' => (float) $row['total']], $workloadRows), JSON_UNESCAPED_SLASHES)) ?>"></canvas></article></section>
<section class="content-card"><div class="card-heading"><div><span class="eyebrow">KANBAN</span><h2>Kanban-Style Request Board</h2></div><a class="btn secondary compact" href="requests.php">Open Requests</a></div><div class="kanban-board"><?php foreach ($requestBoardRows as $row): ?><a class="kanban-lane" href="requests.php?status=<?= e($row['status']) ?>"><span><?= e(str_replace('_', ' ', $row['status'])) ?></span><b><?= number_format((int) $row['total']) ?></b><small>request(s)</small></a><?php endforeach; ?></div></section>
<section class="content-card"><div class="card-heading"><div><span class="eyebrow">SUPPLIERS</span><h2>Supplier Lead-Time Performance Report</h2></div></div><div class="table-wrap"><table class="data modern-table" data-sortable-table><thead><tr><th>Supplier</th><th>POs</th><th>On Time</th><th>Average Lead Time</th><th>Late Orders</th><th>Variance</th><th>Score</th></tr></thead><tbody><?php foreach ($supplierRows as $row): ?><tr><td><b><?= e($row['company']) ?></b></td><td><?= (int) $row['po_count'] ?></td><td><?= money_or_qty($row['on_time_rate']) ?>%</td><td><?= money_or_qty($row['average_lead_time_days']) ?> days</td><td><?= (int) $row['late_orders'] ?></td><td><?= money_or_qty($row['variance_rate']) ?>%</td><td><b><?= money_or_qty($row['reliability_score']) ?>%</b></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="split-grid"><article class="content-card"><div class="card-heading"><div><span class="eyebrow">OVERDUE</span><h2>Purchase Order Overdue Tracker</h2></div></div><div class="table-wrap"><table class="data modern-table" data-sortable-table><thead><tr><th>PO</th><th>Supplier</th><th>Expected</th><th>Days</th><th>Status</th></tr></thead><tbody><?php if (!$overdueRows): ?><tr><td colspan="5" class="muted">No overdue purchase orders.</td></tr><?php endif; ?><?php foreach ($overdueRows as $row): ?><tr><td><a class="table-action" href="purchase_order_view.php?id=<?= (int) $row['id'] ?>"><?= e($row['po_no']) ?></a></td><td><?= e($row['company']) ?></td><td><?= e(date('M d, Y', strtotime($row['expected_delivery']))) ?></td><td><?= (int) $row['overdue_days'] ?></td><td><span class="workflow-badge notify-danger"><?= e($row['status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></article><article class="content-card"><div class="card-heading"><div><span class="eyebrow">VARIANCE</span><h2>Partial Delivery Variance Report</h2></div></div><div class="table-wrap"><table class="data modern-table" data-sortable-table><thead><tr><th>PO</th><th>Material</th><th>Ordered</th><th>Received</th><th>Variance</th></tr></thead><tbody><?php foreach ($varianceRows as $row): ?><tr><td><?= e($row['po_no']) ?><small><?= e($row['company']) ?></small></td><td><?= e($row['material_code']) ?><small><?= e($row['material_name']) ?></small></td><td><?= money_or_qty($row['ordered_qty']) ?></td><td><?= money_or_qty($row['received_qty']) ?></td><td><b><?= money_or_qty($row['variance_qty']) ?></b></td></tr><?php endforeach; ?></tbody></table></div></article></section>
<section class="content-card"><div class="card-heading"><div><span class="eyebrow">QUOTES</span><h2>Supplier Quotation Comparison</h2></div></div><div class="table-wrap"><table class="data modern-table" data-sortable-table><thead><tr><th>Quote</th><th>Material</th><th>Supplier</th><th>Unit Price</th><th>Lead Time</th><th>Validity</th><th>Status</th></tr></thead><tbody><?php foreach ($quoteRows as $row): ?><tr><td><?= e($row['quote_no']) ?></td><td><?= e($row['material_code']) ?><small><?= e($row['material_name']) ?></small></td><td><?= e($row['company']) ?></td><td><?= number_format((float) $row['unit_price'], 2) ?></td><td><?= (int) $row['lead_time_days'] ?> days</td><td><?= $row['validity_date'] ? e(date('M d, Y', strtotime($row['validity_date']))) : 'Open' ?></td><td><span class="workflow-badge"><?= e($row['status']) ?></span></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="content-card"><div class="card-heading"><div><span class="eyebrow">DRAFTS</span><h2>Low-Stock Auto-Create Purchase Request Draft</h2></div></div><div class="table-wrap"><table class="data modern-table" data-sortable-table><thead><tr><th>Material</th><th>Location</th><th>Available</th><th>Reorder Point</th><th>Suggested PR Qty</th><th>Action</th></tr></thead><tbody><?php foreach ($lowStockDrafts as $row): ?><tr><td><?= e($row['material_code']) ?><small><?= e($row['material_name']) ?></small></td><td><?= e($row['location_name']) ?></td><td><?= money_or_qty($row['available_qty']) ?> <?= e($row['unit_name']) ?></td><td><?= money_or_qty($row['reorder_point']) ?></td><td><b><?= money_or_qty($row['draft_qty']) ?></b></td><td><?php if (role_can((string) ($_SESSION['role'] ?? ''), 'manage_procurement')): ?><a class="table-action" href="purchase_request_create.php">Draft PR</a><?php else: ?><span class="muted">View only</span><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<section class="split-grid"><article class="content-card"><div class="card-heading"><div><span class="eyebrow">PROJECTS</span><h2>Project/Site Consumption Trend Report</h2></div></div><div class="table-wrap"><table class="data modern-table" data-sortable-table><thead><tr><th>Site</th><th>Period</th><th>Consumed Qty</th></tr></thead><tbody><?php foreach ($trendRows as $row): ?><tr><td><?= e($row['site_name'] ?? 'Central') ?></td><td><?= e($row['period_label']) ?></td><td><?= money_or_qty($row['consumed_qty']) ?></td></tr><?php endforeach; ?></tbody></table></div></article><article class="content-card"><div class="card-heading"><div><span class="eyebrow">BUDGETS</span><h2>Budget/Cost Tracking per Project</h2></div></div><div class="table-wrap"><table class="data modern-table" data-sortable-table><thead><tr><th>Site</th><th>Budget</th><th>Spent</th><th>Remaining</th></tr></thead><tbody><?php foreach ($budgetRows as $row): ?><tr><td><?= e($row['site_name']) ?></td><td><?= number_format((float) $row['budget_amount'], 2) ?></td><td><?= number_format((float) $row['spent_amount'], 2) ?></td><td><b><?= number_format((float) $row['budget_amount'] - (float) $row['spent_amount'], 2) ?></b></td></tr><?php endforeach; ?></tbody></table></div></article></section>
</div></main></div></body></html>
